from abc import ABC, abstractmethod

# The abstract class, a skeletal framework for your ephemeral sorting needs.
class SortAlgorithm(ABC):
    @abstractmethod
    def sort(self, data):
        """The template method, defining the algorithm's skeletal structure."""
        pass

    @abstractmethod
    def compare(self, a, b):
        """An abstract method for comparing elements, to be defined by the concrete.
        Returns True if a should precede b.
        """
        pass

    @abstractmethod
    def swap(self, data, i, j):
        """An abstract method for swapping elements, a necessary, if crude, operation.
        """
        pass

# BubbleSort: A rather simplistic, yet illustrative, method.
class BubbleSort(SortAlgorithm):
    def sort(self, data):
        n = len(data)
        for i in range(n):
            for j in range(0, n - i - 1):
                if not self.compare(data[j], data[j + 1]):
                    self.swap(data, j, j + 1)
        return data

    def compare(self, a, b):
        # For integers, a simple numerical comparison.
        return a <= b

    def swap(self, data, i, j):
        data[i], data[j] = data[j], data[i]

# SelectionSort: Another rudimentary approach, selecting the smallest element.
class SelectionSort(SortAlgorithm):
    def sort(self, data):
        n = len(data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if not self.compare(data[min_idx], data[j]):
                    min_idx = j
            if min_idx != i:
                self.swap(data, i, min_idx)
        return data

    def compare(self, a, b):
        # Again, for integers, a straightforward comparison.
        return a <= b

    def swap(self, data, i, j):
        data[i], data[j] = data[j], data[i]

